// frontend/mutations/account/editGeneralInfo.ts
import { editCanvasserGeneralInfo, type CanvasserGeneralInfoForm } from '~/client';

export interface EditGeneralInfoParams {
  userId: string;
  body: CanvasserGeneralInfoForm;
}

export const useEditCanvasserGeneralInfo = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: EditGeneralInfoParams) =>
      editCanvasserGeneralInfo({
        composable: '$fetch',
        path: { user_id: params.userId },
        body: params.body,
      }),
    onSuccess: () => {
      showToastSuccess('General information updated successfully');
    },
    onError: (error) => showToastError(error),
  });

  return {
    editCanvasserGeneralInfo: mutateAsync,
    isEditingGeneralInfo: computed(() => asyncStatus.value === 'loading'),
  };
});
