<template>
  <section class="flex flex-col w-full gap-6">
    <PageTitle :title="`${userDetails.first_name} ${userDetails.last_name}`" />
    <section class="flex flex-col gap-4">
      <GoBackButton subject="user" :fallback-to="{ name: 'users-id-canvasser-application', params: { id: userId } }" />
      <CanvasserFormWrapper title="Edit General Information">
        <AppEmpty v-if="!generalInfo" subject="general information" />
        <GeneralInfoForm
          v-else
          variant="edit"
          :initial-data="generalInfo"
          submit-label="Save"
          :is-saving="isSaving"
          guard-unsaved-changes
          :on-submit="onSubmit"
        />
      </CanvasserFormWrapper>
    </section>
  </section>
</template>

<script setup lang="ts">
import type { CanvasserGeneralInfoForm, GetUserDetailsResponse } from '~/client';
import { useEditCanvasserGeneralInfo } from '~/mutations/account';

definePageMeta({
  roles: ['admin'],
});

const { userDetails } = defineProps<{ userDetails: NonNullable<GetUserDetailsResponse> }>();

const userId = computed(() => userDetails.id);
const generalInfo = computed(() => userDetails.canvasser_general_info);

useHead({ title: 'Edit General Information' });

const { editCanvasserGeneralInfo } = useEditCanvasserGeneralInfo();
const queryCache = useQueryCache();

// Drives the Save button's loading state for the duration of the request + refetch.
const isSaving = ref(false);

// Saving stays on this page; invalidating ['user'] refetches the parent query that feeds
// `userDetails`, so the form refreshes in place with the saved values.
const onSubmit = async (values: CanvasserGeneralInfoForm) => {
  isSaving.value = true;
  try {
    await editCanvasserGeneralInfo({ userId: userId.value, body: values });
    await queryCache.invalidateQueries({ key: ['user', userId.value] });
  } finally {
    isSaving.value = false;
  }
};
</script>
